 function matches(s,p,x,f={}){const c=card(x),d=s.players[p].battle.includes(x)?effective(x,s):c;return (!f.creature||c.type==='creature')&&(!f.element||['creature','seed','gear','field'].includes(c.type))&&(!f.nonEvolution||!c.evolution&&!c.sMax)&&(!f.evolution||!!c.evolution)&&(!f.notRace||!race(d,f.notRace))&&(!f.race||race(d,f.race))&&(!f.raceAny||f.raceAny.some(q=>race(d,q)))&&(!f.name||c.name.includes(f.name))&&(!f.exactId||c.id===f.exactId)&&(!f.exactUid||x.uid===f.exactUid)&&(f.exactCost===undefined||cost(c)===f.exactCost)&&(f.belowPower===undefined||api.power(x,false,s)<f.belowPower)&&(!f.color||colors(d).includes(f.color))&&(!f.notColor||!colors(d).includes(f.notColor))&&(!f.multi||colors(d).length>1)&&(!f.spell||faces(c).some(c=>c.type==='spell'))&&(!f.twin||!!c.spellFace)&&(f.max===undefined||cost(d)<=f.max)&&(f.minPower===undefined||api.power(x,false,s)>=f.minPower)&&(f.maxPower===undefined||api.power(x,false,s)<=f.maxPower)&&(!f.untapped||!x.tapped);}
