 const reserved=own=>new Set(Object.entries(own).filter(([k,v])=>Array.isArray(v)&&/Protected$|Reveals$/.test(k)).flatMap(([,v])=>v));
 function look(s,t){if(api.deckLocked(s,t.p))return[];const own=s.players[t.p],skip=reserved(own),xs=own.deck.filter(x=>!skip.has(x.uid)).slice(0,t.n||3);(own.g34Protected??=[]).push(...xs.map(x=>x.uid));api.log(s,t.p,t.public?'reveal':'look',card(t.source).name+'：山札の上'+xs.length+'枚'+(t.public?'を公開：'+xs.map(x=>card(x).name).join('・'):'を確認'),{cardId:t.source});return xs.map(x=>x.uid);}
