 function zoneMove(s,p,from,uid,to,t={}){const own=s.players[p];if(from==='battle'){move(s,[{player:p,uid,to,destroy:to==='grave',controller:t.controller??p}]);return;}const x=remove(own[from],uid);if(!x)return;if(from==='deck')release(s,p,uid);let dest=to;if(from==='deck'&&['mana','shields'].includes(to)&&api.deckRedirect(s,p))dest='grave';if(to==='mana'&&api.manaRedirect(s,p))dest='grave';clear(x,dest);if(t.tapped&&dest==='mana')x.tapped=true;api.addZone(s,p,dest,x);if(dest==='shields')api.notifyShieldAdded(s,p,x);}
